package com.bank.statement;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class StatementReverseDemo {
    private static final Logger log = Logger.getLogger(StatementReverseDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        // Rajesh's amounts stored oldest first
        BigDecimal[] amounts = {
            new BigDecimal("1000.00"),
            new BigDecimal("2000.00"),
            new BigDecimal("3000.00"),
            new BigDecimal("4000.00")
        };

        log.info(() -> "Before (oldest first): " + Arrays.toString(amounts));

        StatementReverser reverser = new StatementReverser();
        reverser.reverseInPlace(amounts);

        log.info(() -> "After (newest first):  " + Arrays.toString(amounts));
    }
}

class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
