package com.bank.statement;

import java.math.BigDecimal;

class StatementReverser {

    // Two-pointer in-place reversal: O(n) time, O(1) extra space.
    void reverseInPlace(BigDecimal[] amounts) {
        if (amounts == null) return;
        int left = 0;
        int right = amounts.length - 1;
        while (left < right) {
            BigDecimal temp = amounts[left];   // hold the left value
            amounts[left] = amounts[right];    // move right into left
            amounts[right] = temp;             // move held value into right
            left++;                            // step inward from the left
            right--;                           // step inward from the right
        }
    }
}
